import{_ as i,o as n,c as u,a2 as w}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Mgawanyiko wa Mazingira ya Uozi Uliounganishwa","description":"","frontmatter":{},"headers":[],"relativePath":"sw/14-修炼境界统一划分.md","filePath":"sw/14-修炼境界统一划分.md","lastUpdated":1789183869000}'),t={name:"sw/14-修炼境界统一划分.md"};function o(k,a,g,m,e,h){return n(),u("div",null,[...a[0]||(a[0]=[w('<h1 id="mgawanyiko-wa-mazingira-ya-uozi-uliounganishwa" tabindex="-1">Mgawanyiko wa Mazingira ya Uozi Uliounganishwa <a class="header-anchor" href="#mgawanyiko-wa-mazingira-ya-uozi-uliounganishwa" aria-label="Permalink to &quot;Mgawanyiko wa Mazingira ya Uozi Uliounganishwa&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>14</td></tr><tr><td>Moduli</td><td>Sheria za Ulimwengu na Mifumo ya Uozi</td></tr><tr><td>Maneno Muhimu</td><td>Mgawanyiko wa Mazingira, Kiwango cha Umoja, Mazingira Tisa, Ulinganishi wa Mifumo, Udhibitisho wa Nanga</td></tr></tbody></table><h2 id="_1-umuhimu-wa-mgawanyiko-wa-mazingira-uliounganishwa" tabindex="-1">1. Umuhimu wa Mgawanyiko wa Mazingira Uliounganishwa <a class="header-anchor" href="#_1-umuhimu-wa-mgawanyiko-wa-mazingira-uliounganishwa" aria-label="Permalink to &quot;1. Umuhimu wa Mgawanyiko wa Mazingira Uliounganishwa&quot;">​</a></h2><p>Kabla ya uundwaji wa ustaarabu wa usawa wa Nanga, kulikuwa na mifumo ya uozi elfu katika Heng Yuan Zhou, na kila mfumo ulikuwa na kiwango chake cha mgawanyiko wa mazingira. Mfumo huu wa mazingira uliochanganya ulisababisha mfululizo wa matatizo: nguvu kati ya waozaji wa mifumo tofauti ilikuwa vigumu kulinganisha, mwingiliano na ushirikiano wa kati ya mifumo ulikosa lugha ya kawaida, mgawanyiko wa rasilimali na tathmini ya hadhi ya kijamii ulikosa msingi wa umoja, na hata ilionekana na hali ya ukosefu wa haki makubwa ya &quot;mazingira sawa lakini nguvu tofauti&quot;.</p><p>Baada ya uundwaji wa ustaarabu wa usawa wa Nanga, ili kutatua tatizo hili, kwa uongozi wa &quot;Kamati ya Viwango vya Uozi&quot; chini ya Baraza la Jamhuri ya Kabila Zote, kwa kushirikiana na waozaji wa mwakilishi wa mifumo mia tatu, baada ya utafiti wa muda mrefu na hoja, &quot;Kiwangwa cha Mgawanyiko wa Mazingira ya Uozi Uliounganishwa&quot; hiki kimeundwa. Kiwango hiki hakitegemei jina la mazingira ya mfumo wowote wa pekee, bali kinachukua vipimo vinne kama viashiria vya msingi: uelewa wa kina wa mzazi wa uozi kuhusu sheria za asili za ulimwengu, usahihi wa udhibiti wa nguvu, kiwango cha mageuzi ya ufahamu, na kiwango cha mchango kwenye mtandao wa usawa, na kuanzisha mfumo wa mgawanyiko wa mazingira unaotumika kwa kila mfumo.</p><p>Kanuni ya msingi ya mgawanyiko wa mazingira uliounganishwa ni &quot;kuzingatia halisi kuliko jina&quot;: haijalishi mfumo gani anatumia mzazi wa uozi, au jina la mazingira ni nini, kwa kadiri halisi yake inafikia kiwango kinacholingana na kiwango cha umoja, anatambuliwa kuwa mazingira hayo. Kanuni hii inahakikisha haki na usawa wa tathmini ya mazingira.</p><h2 id="_2-muhtasari-wa-mazingira-tisa" tabindex="-1">2. Muhtasari wa Mazingira Tisa <a class="header-anchor" href="#_2-muhtasari-wa-mazingira-tisa" aria-label="Permalink to &quot;2. Muhtasari wa Mazingira Tisa&quot;">​</a></h2><p>Kiwangwa cha mgawanyiko wa mazingira uliounganishwa kinagawanya safari ya mageuzi ya mzazi wa uozi katika mazingira tisa, kutoka chini hadi juu kwa mpangilio:</p><table tabindex="0"><thead><tr><th>Nambari ya Mazingira</th><th>Jina la Mazingira</th><th>Tabia ya Msingi</th><th>Ulinganishi wa Takriban na Mazingira ya Misingi Mitatu ya Asili</th><th>Jukumu la Kijamii</th></tr></thead><tbody><tr><td>Mazingira ya Kwanza</td><td>Mazingira ya Uelewa wa Nguvu</td><td>Anagundua awali uwepo wa nguvu za ulimwengu na sheria, na anaanza uozi wa rasmi</td><td>Uelewa wa Awali / Uelewa wa Maisha / Kujua Nafasi</td><td>Mwanafunzi Mpya</td></tr><tr><td>Mazingira ya Pili</td><td>Mazingira ya Uingizaji wa Nguvu</td><td>Uwezo wa kununua na kuingiza nguvu kwa uthabiti, kuanzisha mzunguko wa msingi wa ndani</td><td>Tathmini / Mzunguko / Kudhibiti Nafasi</td><td>Mzazi wa Uozi wa Awali</td></tr><tr><td>Mazingira ya Tatu</td><td>Mazingira ya Mabadiliko ya Nguvu</td><td>Usafi wa nguvu unafikia kiwango cha juu, uwezo wa kubadilisha nguvu kuwa matumizi anuwai</td><td>Kurudia / Maisha Yanayoendelea / Kubadilisha Nafasi</td><td>Mzazi wa Uozi wa Kati</td></tr><tr><td>Mazingira ya Nne</td><td>Mazingira ya Nguvu ya Sheria</td><td>Anaanza kuelewa na kudhibiti sheria, nguvu na sheria zinachanganya awali</td><td>Mchanganyiko / Mabadiliko ya Maisha / Nafasi ya Sheria</td><td>Mzazi wa Uozi wa Juu</td></tr><tr><td>Mazingira ya Tano</td><td>Mazingira ya Nguvu ya Dao</td><td>Anaelewa kwa kina sheria za uwanja fulani, na anajenga &quot;Dao&quot; ya kibinafsi</td><td>Asili / Maisha ya Asili / Nafasi ya Asili</td><td>Mzazi wa Uozi wa Kiwango cha Bwana</td></tr><tr><td>Mazingira ya Sita</td><td>Mazingira ya Umoja na Dao</td><td>Dao ya kibinafsi na sheria za asili za ulimwengu zinachanganya kwa kina, kila hatua inalingana na Dao</td><td>Zaidi ya Mazingira ya Tano ya mfumo wa pekee</td><td>Mzazi wa Uozi wa Kiwango cha Bwana Mkuu</td></tr><tr><td>Mazingira ya Saba</td><td>Mazingira ya Kupasua Mipaka</td><td>Uwezo wa kupasua mipaka ya sheria za njia, kufanya uendeshaji wa uthabiti wa kati ya njia</td><td>—</td><td>Mtu Mwenye Nguvu wa Kiwango cha Njia</td></tr><tr><td>Mazingira ya Nane</td><td>Mazingira ya Uumbaji</td><td>Uwezo wa kuunda ulimwengu kamili na mfumo wa sheria katika nafasi iliyotengwa</td><td>—</td><td>Mtu Mwenye Nguvu wa Kiwango cha Ulimwengu</td></tr><tr><td>Mazingira ya Tisa</td><td>Mazingira ya Asili</td><td>Anagusa asili ya ulimwengu, na uwezo wa kushiriki katika marekebisho madogo na uboreshaji wa sheria za ulimwengu</td><td>—</td><td>Mtu Mwenye Nguvu wa Kiwango cha Ulimwengu</td></tr></tbody></table><p>Kati ya mazingira tisa, mazingira ya kwanza hadi ya tano ni &quot;Mazingira Tano ya Uozi wa Kawaida&quot;, ambayo waozaji wengi wanaweza kufikia kwa juhudi; mazingira ya sita hadi ya tisa ni &quot;Mazingira Nne ya Uozi Takatifu&quot;, ambayo inahitaji talanta, fursa, na juhudi za kiwango cha juu sana kufikiwa, na uvunji wa kila mazingira ni tukio la kimbunga la kiwango cha ulimwengu.</p><h2 id="_3-viwango-vya-maelezo-ya-kila-mazingira" tabindex="-1">3. Viwango vya Maelezo ya Kila Mazingira <a class="header-anchor" href="#_3-viwango-vya-maelezo-ya-kila-mazingira" aria-label="Permalink to &quot;3. Viwango vya Maelezo ya Kila Mazingira&quot;">​</a></h2><h3 id="_3-1-mazingira-ya-kwanza-mazingira-ya-uelewa-wa-nguvu" tabindex="-1">3.1 Mazingira ya Kwanza: Mazingira ya Uelewa wa Nguvu <a class="header-anchor" href="#_3-1-mazingira-ya-kwanza-mazingira-ya-uelewa-wa-nguvu" aria-label="Permalink to &quot;3.1 Mazingira ya Kwanza: Mazingira ya Uelewa wa Nguvu&quot;">​</a></h3><p>Mazingira ya Uelewa wa Nguvu ni kianzio cha uozi, na msingi wake ni &quot;uelewa&quot;. Viwango vya kufikia Mazingira ya Uelewa wa Nguvu vinajumuisha:</p><ul><li>Uwezo wa kugundua kwa uthabiti nguvu zinazotiririka katika ulimwengu (nishati ya roho, nguvu ya sheria, n.k.)</li><li>Uwezo wa kununua kiasi kidogo cha nguvu ndani ya mwili kupitia njia za msingi za uozi</li><li>Kuanzisha ufahamu wa awali wa uelewa wa nguvu, uwezo wa kutofautisha aina tofauti za nguvu</li><li>Ubora wa mwili una marekebisho ya awali kutokana na uingizaji wa nguvu</li></ul><p>Waozaji wa Mazingira ya Uelewa wa Nguvu ni &quot;wanafunzi wapya&quot; katika jamii, na kazi yao kuu ni kujenga msingi na kupata mfumo wa uozi unaofaa kwao wenyewe. Uvunji wa Mazingira ya Uelewa wa Nguvu kwa kawaida unahitaji uozi wa rasmi wa wiki kadhaa hadi miezi kadhaa.</p><h3 id="_3-2-mazingira-ya-pili-mazingira-ya-uingizaji-wa-nguvu" tabindex="-1">3.2 Mazingira ya Pili: Mazingira ya Uingizaji wa Nguvu <a class="header-anchor" href="#_3-2-mazingira-ya-pili-mazingira-ya-uingizaji-wa-nguvu" aria-label="Permalink to &quot;3.2 Mazingira ya Pili: Mazingira ya Uingizaji wa Nguvu&quot;">​</a></h3><p>Msingi wa Mazingira ya Uingizaji wa Nguvu ni &quot;uingizaji&quot;. Viwango vya kufikia Mazingira ya Uingizaji wa Nguvu vinajumuisha:</p><ul><li>Uwezo wa kununua nguvu za ulimwengu kwa uthabiti na kuingiza kuwa akiba ya nguvu inayotumika ndani ya mwili</li><li>Kuanzisha mfumo wa mzunguko wa msingi wa ndani, nguvu inaweza kuzunguka ndani ya mwili kufuata njia mahususi</li><li>Uwezo wa kutumia nguvu iliyoingizwa kwa matumizi ya msingi ya shambulio-ulinzi au msaada</li><li>Usafi wa nguvu unafikia kiwango cha msingi, haina uchafuzi wa kiwango cha juu</li></ul><p>Waozaji wa Mazingira ya Uingizaji wa Nguvu tayari wana utambulisho wa msingi kama waozaji, na wanaweza kushiriki katika kazi kadhaa za uozi za kiwango cha chini na huduma za kijamii. Uvunji wa Mazingira ya Uingizaji wa Nguvu kwa kawaida unahitaji uozi wa miezi kadhaa hadi miaka kadhaa.</p><h3 id="_3-3-mazingira-ya-tatu-mazingira-ya-mabadiliko-ya-nguvu" tabindex="-1">3.3 Mazingira ya Tatu: Mazingira ya Mabadiliko ya Nguvu <a class="header-anchor" href="#_3-3-mazingira-ya-tatu-mazingira-ya-mabadiliko-ya-nguvu" aria-label="Permalink to &quot;3.3 Mazingira ya Tatu: Mazingira ya Mabadiliko ya Nguvu&quot;">​</a></h3><p>Msingi wa Mazingira ya Mabadiliko ya Nguvu ni &quot;mabadiliko&quot;. Viwango vya kufikia Mazingira ya Mabadiliko ya Nguvu vinajumuisha:</p><ul><li>Usafi wa nguvu unafikia kiwango cha juu, uwezo wa kubadilisha aina moja ya nguvu kuwa aina nyingine ya nguvu</li><li>Uwezo wa kufanya mwingiliano wa awali kati ya nguvu na nyenzo (kama vile kuambatisha nguvu kwenye vitu, kuunda umbo la nguvu, n.k.)</li><li>Mzunguko wa ndani ni thabiti na wenye ufanisi, kasi ya kujirejesha kwa nguvu inaongezeka kwa kiwango kikubwa</li><li>Anaanza kugundua uwepo na kazi ya sheria</li></ul><p>Waozaji wa Mazingira ya Mabadiliko ya Nguvu ni nguvu ya msingi katika jamii, na wanaweza kuchukua nafasi kama walimu wa kati, wataalamu wa kiufundi, wasimamizi wa msingi, n.k. Uvunji wa Mazingira ya Mabadiliko ya Nguvu kwa kawaida unahitaji uozi wa miaka kadhaa hadi zaidi ya muongo mmoja.</p><h3 id="_3-4-mazingira-ya-nne-mazingira-ya-nguvu-ya-sheria" tabindex="-1">3.4 Mazingira ya Nne: Mazingira ya Nguvu ya Sheria <a class="header-anchor" href="#_3-4-mazingira-ya-nne-mazingira-ya-nguvu-ya-sheria" aria-label="Permalink to &quot;3.4 Mazingira ya Nne: Mazingira ya Nguvu ya Sheria&quot;">​</a></h3><p>Msingi wa Mazingira ya Nguvu ya Sheria ni &quot;sheria&quot;. Viwango vya kufikia Mazingira ya Nguvu ya Sheria vinajumuisha:</p><ul><li>Uwezo wa kuelewa na kudhibiti awali sheria za msingi za uwanja fulani</li><li>Nguvu na sheria zinachanganya awali, na kutoa aina ya nguvu ya kiwango cha juu inayoitwa &quot;nguvu ya sheria&quot;</li><li>Uwezo wa kutumia mbinu na uwezo zinazotegemea sheria</li><li>Nguvu ya ufahamu inaongezeka kwa kiwango kikubwa, uwezo wa kufanya tathmini za kina na kutafakari kwa muda mrefu</li></ul><p>Waozaji wa Mazingira ya Nguvu ya Sheria ni talanta za kiwango cha juu katika jamii, na wanaweza kuchukua nafasi kama walimu wa juu, wataalamu wa kiufundi, wasimamizi wa kati, n.k. Uvunji wa Mazingira ya Nguvu ya Sheria kwa kawaida unahitaji uozi wa zaidi ya muongo mmoja hadi miongo kadhaa, na ni kizuizi kikuu cha kwanza katika maisha ya waozaji wengi.</p><h3 id="_3-5-mazingira-ya-tano-mazingira-ya-nguvu-ya-dao" tabindex="-1">3.5 Mazingira ya Tano: Mazingira ya Nguvu ya Dao <a class="header-anchor" href="#_3-5-mazingira-ya-tano-mazingira-ya-nguvu-ya-dao" aria-label="Permalink to &quot;3.5 Mazingira ya Tano: Mazingira ya Nguvu ya Dao&quot;">​</a></h3><p>Msingi wa Mazingira ya Nguvu ya Dao ni &quot;kufikia Dao&quot;. Viwango vya kufikia Mazingira ya Nguvu ya Dao vinajumuisha:</p><ul><li>Uelewa wa kimfumo na wa kina kuhusu sheria za uwanja fulani, na uundwaji wa &quot;Dao&quot; ya kipekee ya kibinafsi</li><li>Dao ya kibinafsi inatoa sauti na sheria za ulimwengu, na uwezo wa kutumia nguvu ya sheria kwa upeo mpana</li><li>Nguvu na sheria zinachanganya kwa kina, na kila hatua ina nguvu ya sheria</li><li>Ufahamu unaendelea hadi kiwango cha juu, na uwezo wa kufanya uelewa wa ufahamu wa kati ya njia</li></ul><p>Waozaji wa Mazingira ya Nguvu ya Dao ni &quot;bwana&quot; wa ustaarabu, na wana mamlaka katika uwanja wao, na wanaweza kuchukua nafasi kama washauri wa kiwango cha ustaarabu, walimu wakubwa, wasimamizi wa juu, n.k. Uvunji wa Mazingira ya Nguvu ya Dao unahitaji talanta na uelewa wa kiwango cha juu sana, na waozaji wengi hawawezi kufikia hata kwa maisha yao yote.</p><h3 id="_3-6-mazingira-ya-sita-mazingira-ya-umoja-na-dao" tabindex="-1">3.6 Mazingira ya Sita: Mazingira ya Umoja na Dao <a class="header-anchor" href="#_3-6-mazingira-ya-sita-mazingira-ya-umoja-na-dao" aria-label="Permalink to &quot;3.6 Mazingira ya Sita: Mazingira ya Umoja na Dao&quot;">​</a></h3><p>Msingi wa Mazingira ya Umoja na Dao ni &quot;umoja na Dao&quot;. Viwango vya kufikia Mazingira ya Umoja na Dao vinajumuisha:</p><ul><li>Dao ya kibinafsi na sheria za asili za ulimwengu zinachanganya kwa kina, na kufikia hali ya &quot;umoja wa mbingu na mwanadamu&quot;</li><li>Uwezo wa kuandika upya njia ya kazi ya sheria za eneo kwa upeo mpana</li><li>Aina ya maisha inaanza kuendelea hadi mwelekeo wa juu, na ina huria kwa sehemu kutoka kwa mipaka ya mwili wa nyenzo</li><li>Uwezo wa kuunda eneo la kibinafsi thabiti (eneo la sheria)</li></ul><p>Waozaji wa Mazingira ya Umoja na Dao ni &quot;bwana mkuu&quot; wa ustaarabu, na ni watu wa juu katika kila uwanja, na wana ushawishi mkubwa katika mwelekeo wa maendeleo ya ustaarabu. Uvunji wa Mazingira ya Umoja na Dao ni tukio la kiwango cha ulimwengu, na unahitaji ushirikiano wa wakati, mahali, na watu.</p><h3 id="_3-7-mazingira-ya-saba-mazingira-ya-kupasua-mipaka" tabindex="-1">3.7 Mazingira ya Saba: Mazingira ya Kupasua Mipaka <a class="header-anchor" href="#_3-7-mazingira-ya-saba-mazingira-ya-kupasua-mipaka" aria-label="Permalink to &quot;3.7 Mazingira ya Saba: Mazingira ya Kupasua Mipaka&quot;">​</a></h3><p>Msingi wa Mazingira ya Kupasua Mipaka ni &quot;kupasua mipaka&quot;. Viwango vya kufikia Mazingira ya Kupasua Mipaka vinajumuisha:</p><ul><li>Uwezo wa kupasua mipaka ya sheria za njia, na kufanya uvukaji wa kati ya njia bila msaada wa nanga</li><li>Uwezo wa kufanya kazi kwenye utando wa njia, kama vile kufungua njia za kati ya njia, kutengeneza mapasuko ya njia, n.k.</li><li>Eneo la kibinafsi linaweza kupanua kuwa nafasi ya kujitegemea ndogo</li><li>Aina ya maisha inakuza zaidi ya mwelekeo wa juu, na uwezo wa kuishi katika mazingira ya sheria za njia tofauti</li></ul><p>Watu wenye nguvu wa Mazingira ya Kupasua Mipaka ni uwepo wa &quot;kiwango cha njia&quot;, na wanaweza kuchukua kazi na jukumu la kiwango cha njia kwa uhuru. Uvunji wa Mazingira ya Kupasua Mipaka ni vigumu sana, na idadi ya waozaji wanaofikia mazingira haya katika Heng Yuan Zhou yote ni mdogo.</p><h3 id="_3-8-mazingira-ya-nane-mazingira-ya-uumbaji" tabindex="-1">3.8 Mazingira ya Nane: Mazingira ya Uumbaji <a class="header-anchor" href="#_3-8-mazingira-ya-nane-mazingira-ya-uumbaji" aria-label="Permalink to &quot;3.8 Mazingira ya Nane: Mazingira ya Uumbaji&quot;">​</a></h3><p>Msingi wa Mazingira ya Uumbaji ni &quot;uumbaji&quot;. Viwango vya kufikia Mazingira ya Uumbaji vinajumuisha:</p><ul><li>Uwezo wa kuunda ulimwengu kamili katika nafasi iliyotengwa, ikiwa ni pamoja na nyenzo, nguvu, sheria, na maisha</li><li>Uwezo wa kubuni na kuunda mfumo wa sheria za msingi wa ulimwengu mpya</li><li>Eneo la kibinafsi linaweza kupanua kuwa ulimwengu kamili</li><li>Aina ya maisha inakaribia uwepo wa mwelekeo wa juu, na uwezo wa kujitokeza katika njia nyingi zaidi kwa wakati mmoja</li></ul><p>Watu wenye nguvu wa Mazingira ya Uumbaji ni uwepo wa &quot;kiwango cha ulimwengu&quot;, na ulimwengu wanaouunda unaweza kutumika kama rasilimali za uozi, maeneo ya majaribio, mahali pa hifadhi ya ustaarabu, n.k. Uvunji wa Mazingira ya Uumbaji ni moja ya matukio yanayotokea sana katika ulimwengu.</p><h3 id="_3-9-mazingira-ya-tisa-mazingira-ya-asili" tabindex="-1">3.9 Mazingira ya Tisa: Mazingira ya Asili <a class="header-anchor" href="#_3-9-mazingira-ya-tisa-mazingira-ya-asili" aria-label="Permalink to &quot;3.9 Mazingira ya Tisa: Mazingira ya Asili&quot;">​</a></h3><p>Msingi wa Mazingira ya Asili ni &quot;asili&quot;. Viwango vya kufikia Mazingira ya Asili vinajumuisha:</p><ul><li>Anagusa sheria za asili za ulimwengu, na uwezo wa kuelewa kanuni za mwisho za kazi za ulimwengu</li><li>Uwezo wa kushiriki katika marekebisho madogo na uboreshaji wa sheria za ulimwengu, na uwezo wa kuathiri mwelekeo wa mageuzi ya ulimwengu</li><li>Aina ya maisha inajenga uhusiano wa kina na asili ya ulimwengu, na karibu ni hai milele</li><li>Uwezo wa kutumia nguvu ya asili kwa kiwango cha ulimwengu</li></ul><p>Watu wenye nguvu wa Mazingira ya Asili ni uwepo wa &quot;kiwango cha ulimwengu&quot;, na ni nguvu ya juu zaidi katika Heng Yuan Zhou. Waozaji wanaofikia Mazingira ya Asili kwa kawaida huitwa &quot;watu wenye nguvu wa juu zaidi wa njia&quot;, na ni kundi lengo la msingi la &quot;Mkakati wa Ushirikishaji wa 20%&quot; wa ustaarabu wa usawa.</p><h2 id="_4-mfumo-wa-udhibitisho-wa-mazingira" tabindex="-1">4. Mfumo wa Udhibitisho wa Mazingira <a class="header-anchor" href="#_4-mfumo-wa-udhibitisho-wa-mazingira" aria-label="Permalink to &quot;4. Mfumo wa Udhibitisho wa Mazingira&quot;">​</a></h2><p>Ili kuhakikisha haki na usahihi wa tathmini ya mazingira, ustaarabu wa usawa umeanzisha mfumo mkali wa udhibitisho wa mazingira:</p><ol><li><strong>Ufuatiliaji wa Kiotomatiki wa Nanga</strong>: Baada ya mzazi wa uozi kuunganishwa kwenye mtandao wa nanga, nanga itafuatilia kila mara viashiria kama vile kiwango chake cha nguvu, uelewa wa sheria, na nguvu ya ufahamu, na wakati viashiria vinafikia kiwango cha mazingira mapya, itatoa onyo kiotomatiki</li><li><strong>Mtihani wa Kamati ya Viwango</strong>: Kwa uvunji wa mazingira kutoka Mazingira ya Nne na juu, inahitajika mtihani rasmi unaandaliwa na Kamati ya Viwango vya Uozi, na maudhui ya mtihani yanajumuisha upande watatu: mtihani wa nadharia, mtihani wa vitendo, na tathmini ya mchango</li><li><strong>Muda wa Ushiriki na Maoni</strong>: Baada ya kufanya mtihani, kufanyika ushiriki kwa siku thelathini, na wakati wa ushiriki maisha yoyote inaweza kuwasilisha maoni, na kama maoni yanathibitishwa, inahitajika mtihani wa tena</li><li><strong>Toa Cheti cha Mazingira</strong>: Baada ya ushiriki bila maoni, mtandao wa nanga utatoa cheti cha mazingira cha umoja, na taarifa za cheti zitaandikwa katika hifadhi ya data ya ustaarabu</li></ol><h2 id="_5-ulinganishi-kati-ya-mazingira-na-haki-jukumu-za-kijamii" tabindex="-1">5. Ulinganishi kati ya Mazingira na Haki-Jukumu za Kijamii <a class="header-anchor" href="#_5-ulinganishi-kati-ya-mazingira-na-haki-jukumu-za-kijamii" aria-label="Permalink to &quot;5. Ulinganishi kati ya Mazingira na Haki-Jukumu za Kijamii&quot;">​</a></h2><p>Waozaji wa mazingira tofauti wanafurahia haki tofauti na wanabeba jukumu tofauti katika ustaarabu wa usawa:</p><table tabindex="0"><thead><tr><th>Mazingira</th><th>Haki za Msingi</th><th>Jukumu za Msingi</th></tr></thead><tbody><tr><td>Uelewa wa Nguvu - Uingizaji wa Nguvu</td><td>Kupata rasilimali za msingi za uozi bila malipo, haki ya kutumia maeneo ya umma ya uozi</td><td>Kuzingatia maadili ya uozi, kushiriki katika huduma za msingi za jamii</td></tr><tr><td>Mabadiliko ya Nguvu - Nguvu ya Sheria</td><td>Haki ya mgawanyiko wa rasilimali za juu, haki ya kuomba sifa ya mwalimu, haki ya kuhamia kwa kati ya mikoa</td><td>Kuwafundisha waozaji wa awali, kushiriki katika utafiti wa kiufundi au huduma za kijamii</td></tr><tr><td>Nguvu ya Dao - Umoja na Dao</td><td>Haki ya mgawanyiko wa rasilimali za kiwango cha juu, haki ya ufikiaji wa juu wa nanga, haki ya kushiriki katika maamuzi ya ustaarabu</td><td>Kubeba miradi ya utafiti ya kiwango cha ustaarabu, kudumisha uthabiti wa nanga za eneo</td></tr><tr><td>Kupasua Mipaka - Uumbaji</td><td>Haki ya mgawanyiko wa rasilimali ya kiwango cha njia, haki ya kuunda nafasi ya kujitegemea, haki ya kushiriki katika masuala ya njia</td><td>Kubeba kazi za kiwango cha njia, kudumisha uthabiti wa utando wa njia, kushiriki katika masuala ya kati ya njia</td></tr><tr><td>Asili</td><td>Haki ya mgawanyiko wa rasilimali ya kiwango cha ulimwengu, haki ya kushiriki katika marekebisho madogo ya sheria, haki ya kushiriki katika maamuzi ya juu zaidi ya ustaarabu</td><td>Kudumisha uthabiti wa jumla wa ulimwengu, kuongoza mwelekeo wa mageuzi ya ustaarabu, kufundisha talanta za ziada</td></tr></tbody></table><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kiwangwa cha mgawanyiko wa mazingira ya uozi uliounganishwa ni moja ya miundombinu ya mfumo wa uozi wa ustaarabu wa usawa wa Nanga. Inatoa &quot;kipimo cha kawaida&quot; kwa mifumo mia tatu ya uozi, na kufanya mwingiliano, ushirikiano, na ushindani wa kati ya mifumo kuwa inawezekana, na pia inatoa msingi wa usawa kwa mgawanyiko wa rasilimali, utawala wa kijamii, na ufundishaji wa talanta. Mgawanyiko wa mazingira tisa hauko kwa ajili ya kuunda tofauti za tabaka, bali kwa ajili ya kubainisha kwa uwazi hatua ya mageuzi ya kila mzazi wa uozi, na kumpatia msaada na mwongozo unaofaa zaidi. Kuongezeka kwa mazingira siko mwisho, bali ni kianzio kipya cha kuelekea mageuzi ya usawa ya kiwango cha juu zaidi.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Muonekano wa Jumla wa Mifumo Mia Tatu ya Uozi wa Asili)</li><li>17-位面至高强者标准 (Kiwangwa cha Watu Wenye Nguvu wa Juu zaidi wa Njia)</li><li>29-共生度评估体系 (Mfumo wa Tathmini ya Kiwango cha Usawa)</li></ul>',57)])])}const l=i(t,[["render",o]]);export{r as __pageData,l as default};
